{"call_id": "call_wcfF0Eu2hNReCAIcwTUCBMPg", "changes": {"c:\WorkApp2\src\App.tsx": {"content": "import {
  AlertTriangle,
  BriefcaseBusiness,
  CalendarClock,
  CheckCircle2,
  ClipboardList,
  FileText,
  GraduationCap,
  HeartPulse,
  Mail,
  Phone,
  Plus,
  RefreshCcw,
  Search,
  UserRound,
} from "lucide-react";
import { useMemo, useState } from "react";
import { agenciesSeed, contactsSeed, parentPathwaysSeed, trainingSeed } from "./data";
import { needsVerification, scoreAgency, trainingScore } from "./scoring";
import type { Agency, Contact, MessageKind, ParentPathwaysState, PersonKey, TrainingOption } from "./types";

const storageKeys = {
  agencies: "upskillapp.agencies",
  training: "upskillapp.training",
  contacts: "upskillapp.contacts",
  parent: "upskillapp.parentPathways",
};

const readStored = <T,>(key: string, fallback: T): T => {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : fallback;
  } catch {
    return fallback;
  }
};

const writeStored = (key: string, value: unknown) => localStorage.setItem(key, JSON.stringify(value));

const profiles = {
  josh: {
    name: "Josh",
    headline: "ICT/MSP support, Microsoft 365, school tech, admin systems, digital training",
    availability: "Needs replacement work for Thursday and Friday. Works Monday/Wednesday 8:30am-5:00pm.",
    focus: "Predictable day work, low-overwhelm steps, ICT/admin/training pathway.",
  },
  kristy: {
    name: "Kristy",
    headline: "Registered Nurse seeking non-aged-care part-time or casual work",
    availability: "Family-friendly shifts where possible.",
    focus: "GP practice, clinic, immunisation, community, school, child/family health, outpatient, hospital pool.",
  },
};

const messageKinds: MessageKind[] = [
  "Josh agency",
  "Kristy agency",
  "Josh training",
  "Kristy training",
  "Parent Pathways",
  "3 day follow-up",
];

function App() {
  const [agencies, setAgencies] = useState<Agency[]>(() => readStored(storageKeys.agencies, agenciesSeed));
  const [training, setTraining] = useState<TrainingOption[]>(() => readStored(storageKeys.training, trainingSeed));
  const [contacts, setContacts] = useState<Contact[]>(() => readStored(storageKeys.contacts, contactsSeed));
  const [parent, setParent] = useState<ParentPathwaysState>(() => readStored(storageKeys.parent, parentPathwaysSeed));
  const [activePerson, setActivePerson] = useState<PersonKey>("josh");
  const [messageKind, setMessageKind] = useState<MessageKind>("Josh agency");
  const [selectedAgencyId, setSelectedAgencyId] = useState(agencies[0]?.id ?? "");
  const [selectedTrainingId, setSelectedTrainingId] = useState(training[0]?.id ?? "");
  const [query, setQuery] = useState("");

  const scoredAgencies = useMemo(
    () =>
      agencies
        .map((agency) => ({ agency, score: scoreAgency(agency) }))
        .sort((a, b) => Math.max(b.score.joshScore, b.score.kristyScore) - Math.max(a.score.joshScore, a.score.kristyScore)),
    [agencies],
  );

  const filteredAgencies = scoredAgencies.filter(({ agency }) =>
    [agency.name, agency.type, agency.location, agency.notes, agency.nextAction, agency.tags.join(" ")]
      .join(" ")
      .toLowerCase()
      .includes(query.toLowerCase()),
  );

  const topJoshAgencies = scoredAgencies.filter(({ score }) => score.joshScore > 0).sort((a, b) => b.score.joshScore - a.score.joshScore).slice(0, 5);
  const topKristyAgencies = scoredAgencies
    .filter(({ score }) => !score.kristyHardPenalty && score.kristyScore > 0)
    .sort((a, b) => b.score.kristyScore - a.score.kristyScore)
    .slice(0, 5);

  const topJoshTraining = training
    .filter((item) => item.person === "josh" || item.person === "both")
    .sort((a, b) => trainingScore(b) - trainingScore(a))
    .slice(0, 5);
  const topKristyTraining = training
    .filter((item) => item.person === "kristy" || item.person === "both")
    .sort((a, b) => trainingScore(b) - trainingScore(a))
    .slice(0, 5);

  const todayAction =
    activePerson === "josh"
      ? topJoshAgencies[0]?.agency.nextAction || "Pick one Josh-friendly agency and make the first contact."
      : topKristyAgencies[0]?.agency.nextAction || "Ask Yilabara about Kristy support and non-aged-care nursing pathways.";

  const selectedAgency = agencies.find((agency) => agency.id === selectedAgencyId) ?? agencies[0];
  const selectedTraining = training.find((item) => item.id === selectedTrainingId) ?? training[0];

  const saveAgencies = (next: Agency[]) => {
    setAgencies(next);
    writeStored(storageKeys.agencies, next);
  };

  const saveTraining = (next: TrainingOption[]) => {
    setTraining(next);
    writeStored(storageKeys.training, next);
  };

  const saveContacts = (next: Contact[]) => {
    setContacts(next);
    writeStored(storageKeys.contacts, next);
  };

  const saveParent = (next: ParentPathwaysState) => {
    setParent(next);
    writeStored(storageKeys.parent, next);
  };

  const addAgency = () => {
    const nextAgency: Agency = {
      id: `agency-${Date.now()}`,
      name: "New agency or provider",
      type: "recruiter",
      location: "Dubbo-relevant",
      phone: "",
      email: "",
      website: "",
      openingHours: "Needs verification",
      helpsWith: ["manual entry"],
      joshRelevance: [],
      kristyRelevance: [],
      eligibilityRules: "Check directly.",
      costs: "Verify before acting.",
      fundingOptions: [],
      servicesOffered: [],
      lastVerified: "",
      confidence: "low",
      notes: "",
      nextAction: "Verify contact details and ask what they can help with.",
      tags: ["manual"],
    };
    saveAgencies([nextAgency, ...agencies]);
    setSelectedAgencyId(nextAgency.id);
  };

  const addCourse = () => {
    const nextCourse: TrainingOption = {
      id: `course-${Date.now()}`,
      person: activePerson,
      course: "New course",
      provider: "Provider to verify",
      cost: "Check cost",
      fundingPossible: "Check funding",
      deliveryMode: "check",
      duration: "Check duration",
      priority: "Maybe later",
      status: "Idea",
      employabilityImpact: 5,
      timeFit: 5,
      costFit: 5,
      fundingAvailability: 5,
      strengthsAlignment: 5,
      availabilityFit: 5,
      stressFit: 5,
      longTermValue: 5,
      jobsUnlocked: [],
      questions: ["What are the days, cost, subsidies, workload, and practical requirements?"],
      notes: "",
      lastVerified: "",
    };
    saveTraining([nextCourse, ...training]);
    setSelectedTrainingId(nextCourse.id);
  };

  const addContact = (agencyId: string) => {
    const nextContact: Contact = {
      id: `contact-${Date.now()}`,
      agencyId,
      personContacted: "",
      channel: "Phone",
      lastContact: new Date().toISOString().slice(0, 10),
      nextFollowUp: "",
      notes: "",
      status: "Waiting",
    };
    saveContacts([nextContact, ...contacts]);
  };

  const resetSeed = () => {
    saveAgencies(agenciesSeed);
    saveTraining(trainingSeed);
    saveContacts(contactsSeed);
    saveParent(parentPathwaysSeed);
  };

  return (
    <main>
      <header className="hero">
        <div className="hero-copy">
          <p className="eyebrow">Dubbo NSW employment support planner</p>
          <h1>UpskillApp</h1>
          <p>
            Find the agencies, training, funding, and next steps that build the bridge between current options and better work.
          </p>
        </div>
        <div className="hero-panel" aria-label="Current focus">
          <div className="toggle-row">
            <button className={activePerson === "josh" ? "active" : ""} onClick={() => setActivePerson("josh")}>
              <UserRound size={16} /> Josh
            </button>
            <button className={activePerson === "kristy" ? "active" : ""} onClick={() => setActivePerson("kristy")}>
              <HeartPulse size={16} /> Kristy
            </button>
          </div>
          <h2>{profiles[activePerson].headline}</h2>
          <p>{profiles[activePerson].availability}</p>
          <p>{profiles[activePerson].focus}</p>
        </div>
      </header>

      <section className="action-band">
        <div>
          <p className="label">Today's best next action</p>
          <h2>{todayAction}</h2>
        </div>
        <button onClick={resetSeed} className="ghost-button">
          <RefreshCcw size={16} /> Reset seed data
        </button>
      </section>

      <section className="dashboard-grid">
        <SummaryPanel
          icon={<BriefcaseBusiness size={20} />}
          title="Josh Pathway"
          items={[
            `Best agency: ${topJoshAgencies[0]?.agency.name ?? "Add an agency"}`,
            `Best course: ${topJoshTraining[0]?.course ?? "Add a course"}`,
            "Short-term: Thursday/Friday day work in ICT, admin, school support, customer service, or digital training.",
            "Long-term: M365 support, TAE/trainer pathway, school ICT, MSP Level 2.",
          ]}
        />
        <SummaryPanel
          icon={<HeartPulse size={20} />}
          title="Kristy Pathway"
          items={[
            `Best support: ${topKristyAgencies[0]?.agency.name ?? "Add a nursing pathway"}`,
            `Best CPD: ${topKristyTraining[0]?.course ?? "Add training"}`,
            "Exclude aged care, RACF, and nursing-home focused options.",
            "Target GP, clinic, community, school, immunisation, outpatient, and family-friendly hospital pool roles.",
          ]}
        />
        <SummaryPanel
          icon={<GraduationCap size={20} />}
          title="Funding"
          items={[
            "Ask Yilabara about Parent Pathways eligibility and individual fund rules.",
            "Check Smart and Skilled and Fee-Free TAFE before committing.",
            "Bring course quotes, check costs, and dates to appointments.",
          ]}
        />
      </section>

      <section className="section-shell">
        <div className="section-heading">
          <div>
            <p className="label">Agency finder and scoring</p>
            <h2>Agency CRM</h2>
          </div>
          <div className="toolbar">
            <label className="search-box">
              <Search size={16} />
              <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Filter agencies" />
            </label>
            <button onClick={addAgency}>
              <Plus size={16} /> Add agency
            </button>
          </div>
        </div>
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Agency</th>
                <th>Type</th>
                <th>Josh</th>
                <th>Kristy</th>
                <th>Priority</th>
                <th>Verification</th>
                <th>Next action</th>
              </tr>
            </thead>
            <tbody>
              {filteredAgencies.map(({ agency, score }) => (
                <tr key={agency.id} onClick={() => setSelectedAgencyId(agency.id)}>
                  <td>
                    <strong>{agency.name}</strong>
                    <span>{score.bestReason}</span>
                  </td>
                  <td>{agency.type}</td>
                  <td>{score.joshScore}</td>
                  <td className={score.kristyHardPenalty ? "warning-text" : ""}>{score.kristyHardPenalty ? "Poor fit" : score.kristyScore}</td>
                  <td><PriorityBadge priority={score.priority} /></td>
                  <td>{needsVerification(agency.lastVerified) ? <Flag text="Verify" /> : <Ok text="Current" />}</td>
                  <td>{agency.nextAction}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {selectedAgency && (
          <div className="detail-grid">
            <EditableAgency agency={selectedAgency} agencies={agencies} saveAgencies={saveAgencies} />
            <QuestionCard title="Exact question to ask" text={scoreAgency(selectedAgency).exactQuestion} concern={scoreAgency(selectedAgency).biggestConcern} />
          </div>
        )}
      </section>

      <section className="section-shell">
        <div className="section-heading">
          <div>
            <p className="label">Pathway planner</p>
            <h2>Training course finder</h2>
          </div>
          <button onClick={addCourse}>
            <Plus size={16} /> Add course
          </button>
        </div>
        <div className="pathway-columns">
          <PathwayList title="Josh top 5" items={topJoshTraining} onSelect={setSelectedTrainingId} />
          <PathwayList title="Kristy top 5" items={topKristyTraining} onSelect={setSelectedTrainingId} />
        </div>
        {selectedTraining && (
          <TrainingDetail item={selectedTraining} training={training} saveTraining={saveTraining} />
        )}
      </section>

      <section className="section-shell">
        <div className="section-heading">
          <div>
            <p className="label">Support and funding</p>
            <h2>Parent Pathways / Yilabara</h2>
          </div>
        </div>
        <div className="parent-grid">
          <TextAreaBlock label="Eligibility" value={parent.eligibility} onChange={(value) => saveParent({ ...parent, eligibility: value })} />
          <TextAreaBlock label="Funding available" value={parent.fundingAvailable} onChange={(value) => saveParent({ ...parent, fundingAvailable: value })} />
          <TextAreaBlock label="Appointment notes" value={parent.appointmentNotes} onChange={(value) => saveParent({ ...parent, appointmentNotes: value })} />
          <div className="checklist">
            <h3>Ask Yilabara</h3>
            {[
              "Is Kristy eligible if she is not receiving Parenting Payment?",
              "Can Parent Pathways pay for nursing CPD, immunisation, police check, WWCC, laptop, phone, transport, or materials?",
              "Can you help Kristy find family-friendly nursing work that is not aged care?",
              "Can you help with return-to-work confidence?",
              "Can you connect us with employers or only training providers?",
              "Can the program support Josh too, or only Kristy?",
              "What is the best first step this week?",
            ].map((item) => (
              <label key={item} className="check-row">
                <input type="checkbox" /> {item}
              </label>
            ))}
          </div>
        </div>
      </section>

      <section className="section-shell">
        <div className="section-heading">
          <div>
            <p className="label">Follow-up system</p>
            <h2>Contact tracker</h2>
          </div>
          <button onClick={() => addContact(selectedAgency?.id ?? agencies[0].id)}>
            <Plus size={16} /> Add follow-up
          </button>
        </div>
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Agency</th>
                <th>Person</th>
                <th>Channel</th>
                <th>Last contact</th>
                <th>Next follow-up</th>
                <th>Status</th>
                <th>Notes</th>
              </tr>
            </thead>
            <tbody>
              {contacts.map((contact) => (
                <tr key={contact.id}>
                  <td>{agencies.find((agency) => agency.id === contact.agencyId)?.name ?? "Unknown"}</td>
                  <td><InlineInput value={contact.personContacted} onChange={(value) => saveContacts(contacts.map((item) => item.id === contact.id ? { ...item, personContacted: value } : item))} /></td>
                  <td>{contact.channel}</td>
                  <td><InlineInput type="date" value={contact.lastContact} onChange={(value) => saveContacts(contacts.map((item) => item.id === contact.id ? { ...item, lastContact: value } : item))} /></td>
                  <td><InlineInput type="date" value={contact.nextFollowUp} onChange={(value) => saveContacts(contacts.map((item) => item.id === contact.id ? { ...item, nextFollowUp: value } : item))} /></td>
                  <td>{contact.status}</td>
                  <td><InlineInput value={contact.notes} onChange={(value) => saveContacts(contacts.map((item) => item.id === contact.id ? { ...item, notes: value } : item))} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      <section className="section-shell">
        <div className="section-heading">
          <div>
            <p className="label">Question and message generator</p>
            <h2>Contact message generator</h2>
          </div>
          <select value={messageKind} onChange={(event) => setMessageKind(event.target.value as MessageKind)}>
            {messageKinds.map((kind) => <option key={kind}>{kind}</option>)}
          </select>
        </div>
        <textarea className="message-output" readOnly value={generateMessage(messageKind, selectedAgency, selectedTraining)} />
      </section>

      <section className="section-shell">
        <div className="section-heading">
          <div>
            <p className="label">WorkApp integration layer</p>
            <h2>Requirement bridge</h2>
          </div>
        </div>
        <div className="bridge-grid">
          {[
            ["TAE40122", "Show Josh's TAE40122 pathway and ask providers about workload, delivery days, placement, and funding."],
            ["Microsoft 365 admin", "Show Microsoft 365 Fundamentals/admin pathway and mark M365 roles as high alignment."],
            ["Immunisation", "Show Kristy's immunisation course and GP/clinic/community nursing direction."],
            ["WWCC or police check", "Create a blocker action to confirm cost, processing time, and whether funding can cover it."],
            ["Factory or warehouse", "Suggest only day-shift bridge work and check WHS/manual handling if it genuinely helps."],
          ].map(([requirement, action]) => (
            <article key={requirement}>
              <h3>{requirement}</h3>
              <p>{action}</p>
            </article>
          ))}
        </div>
      </section>
    </main>
  );
}

function SummaryPanel({ icon, title, items }: { icon: React.ReactNode; title: string; items: string[] }) {
  return (
    <article className="summary-panel">
      <div className="panel-title">{icon}<h2>{title}</h2></div>
      <ul>{items.map((item) => <li key={item}>{item}</li>)}</ul>
    </article>
  );
}

function PriorityBadge({ priority }: { priority: string }) {
  return <span className={`priority ${priority.toLowerCase().replaceAll(" ", "-")}`}>{priority}</span>;
}

function Flag({ text }: { text: string }) {
  return <span className="flag"><AlertTriangle size={14} /> {text}</span>;
}

function Ok({ text }: { text: string }) {
  return <span className="ok"><CheckCircle2 size={14} /> {text}</span>;
}

function EditableAgency({ agency, agencies, saveAgencies }: { agency: Agency; agencies: Agency[]; saveAgencies: (agencies: Agency[]) => void }) {
  const patch = (updates: Partial<Agency>) => saveAgencies(agencies.map((item) => item.id === agency.id ? { ...item, ...updates } : item));

  return (
    <article className="detail-card">
      <h3>{agency.name}</h3>
      <div className="form-grid">
        <label>Name<input value={agency.name} onChange={(event) => patch({ name: event.target.value })} /></label>
        <label>Phone<input value={agency.phone} onChange={(event) => patch({ phone: event.target.value })} /></label>
        <label>Email<input value={agency.email} onChange={(event) => patch({ email: event.target.value })} /></label>
        <label>Last verified<input type="date" value={agency.lastVerified} onChange={(event) => patch({ lastVerified: event.target.value })} /></label>
      </div>
      <label>Next action<textarea value={agency.nextAction} onChange={(event) => patch({ nextAction: event.target.value })} /></label>
      <label>Notes<textarea value={agency.notes} onChange={(event) => patch({ notes: event.target.value })} /></label>
    </article>
  );
}

function QuestionCard({ title, text, concern }: { title: string; text: string; concern: string }) {
  return (
    <article className="detail-card question-card">
      <h3>{title}</h3>
      <p className="quoted">{text}</p>
      <p><strong>Biggest concern:</strong> {concern}</p>
    </article>
  );
}

function PathwayList({ title, items, onSelect }: { title: string; items: TrainingOption[]; onSelect: (id: string) => void }) {
  return (
    <article className="pathway-list">
      <h3>{title}</h3>
      {items.map((item) => (
        <button key={item.id} onClick={() => onSelect(item.id)}>
          <span>
            <strong>{item.course}</strong>
            <small>{item.provider} | {item.deliveryMode} | {item.duration}</small>
          </span>
          <b>{trainingScore(item)}</b>
        </button>
      ))}
    </article>
  );
}

function TrainingDetail({ item, training, saveTraining }: { item: TrainingOption; training: TrainingOption[]; saveTraining: (training: TrainingOption[]) => void }) {
  const patch = (updates: Partial<TrainingOption>) => saveTraining(training.map((course) => course.id === item.id ? { ...course, ...updates } : course));

  return (
    <article className="detail-card">
      <div className="panel-title"><GraduationCap size={20} /><h3>{item.course}</h3><PriorityBadge priority={item.priority} /></div>
      <div className="form-grid">
        <label>Course<input value={item.course} onChange={(event) => patch({ course: event.target.value })} /></label>
        <label>Provider<input value={item.provider} onChange={(event) => patch({ provider: event.target.value })} /></label>
        <label>Cost<input value={item.cost} onChange={(event) => patch({ cost: event.target.value })} /></label>
        <label>Duration<input value={item.duration} onChange={(event) => patch({ duration: event.target.value })} /></label>
      </div>
      <div className="detail-columns">
        <div>
          <h4>Why it helps</h4>
          <p>{item.notes}</p>
          <h4>Jobs it unlocks</h4>
          <p>{item.jobsUnlocked.join(", ") || "Add target jobs."}</p>
        </div>
        <div>
          <h4>Questions to ask</h4>
          <ul>{item.questions.map((question) => <li key={question}>{question}</li>)}</ul>
        </div>
      </div>
    </article>
  );
}

function TextAreaBlock({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) {
  return <label className="textarea-block">{label}<textarea value={value} onChange={(event) => onChange(event.target.value)} /></label>;
}

function InlineInput({ value, onChange, type = "text" }: { value: string; onChange: (value: string) => void; type?: string }) {
  return <input className="inline-input" type={type} value={value} onChange={(event) => onChange(event.target.value)} />;
}

function generateMessage(kind: MessageKind, agency?: Agency, training?: TrainingOption) {
  const targetName = agency?.name ?? "there";
  const courseName = training?.course ?? "the course";
  const provider = training?.provider ?? "your provider";

  if (kind === "Josh agency") {
    return `Hi ${targetName},\n\nMy name is Josh Parris and I live in Dubbo. I am looking for Thursday/Friday day work because I currently work Monday and Wednesday in ICT/MSP support.\n\nMy background includes ICT support, Microsoft 365, troubleshooting, service desk, customer service, school ICT, classroom technology, ViewBoard training, documentation, process improvement, and AI-assisted workflows.\n\nI am open to ICT support, admin, customer service, school support, digital training, or suitable predictable day-shift work.\n\nDo you currently have any Dubbo roles that could fit Thursday/Friday availability?`;
  }

  if (kind === "Kristy agency") {
    return `Hi ${targetName},\n\nKristy Parris is a Registered Nurse in Dubbo looking for part-time or casual nursing work. She is not looking for aged care or residential aged care.\n\nShe is interested in GP practice, clinic, community, school, child/family health, outpatient, immunisation, or hospital casual pool roles. Family-friendly options are preferred where possible.\n\nDo you currently know of any suitable non-aged-care RN roles in Dubbo?`;
  }

  if (kind === "Josh training") {
    return `Hi ${provider},\n\nI am checking whether ${courseName} would suit my current work situation. I work Monday and Wednesday in ICT/MSP support and I am looking to improve my Thursday/Friday work options and longer-term ICT/training pathway.\n\nCould you please confirm delivery mode, days/times, cost, subsidies or fee-free availability, online/in-person/blended options, start dates, weekly workload, assessment requirements, and whether it suits parents or part-time workers?`;
  }

  if (kind === "Kristy training") {
    return `Hi ${provider},\n\nKristy Parris is an RN in Dubbo looking at ${courseName} to support part-time or casual non-aged-care nursing work, especially GP practice, clinic, community, school, child/family health, outpatient, or immunisation roles.\n\nCould you please confirm delivery mode, days/times, cost, subsidies, start dates, workload per week, practical requirements, and whether this pathway is recognised for NSW nursing roles?`;
  }

  if (kind === "Parent Pathways") {
